//###########################################################
syncLegendVisibility = function() {
  var el, j, legendSeriesEls, len, seriesKey;
  legendSeriesEls = document.querySelectorAll('#chart-components-tab .legend-series');
  for (j = 0, len = legendSeriesEls.length; j < len; j++) {
    el = legendSeriesEls[j];
    seriesKey = el.getAttribute('series-key');
    if (seriesKey && seriesVisibility.hasOwnProperty(seriesKey)) {
      if (seriesVisibility[seriesKey]) {
        el.classList.add('visible');
      } else {
        el.classList.remove('visible');
      }
    }
  }
};

