export var setSelectedRegion = function(selReg, force) {
  var endIdx, isDelta, maxIdx, startIdx;
  log("setSelectedRegion");
  if (selReg == null) {
    return;
  }
  if (!force) {
    if (selection == null) {
      return;
    }
  }
  if (selection == null) {
    selection = Object.create(null);
  }
  ({startIdx, endIdx, isDelta} = selReg);
  if (!isDelta && selection.startIdx === startIdx && selection.endIdx === endIdx) { //# nothing to update
    return;
  } else if (!isDelta) { // at least one new value to set
    selection.startIdx = startIdx;
    selection.endIdx = endIdx; // apply delta
  } else {
    if (startIdx != null) {
      selection.startIdx += startIdx;
    }
    if (endIdx != null) {
      selection.endIdx += endIdx;
    }
  }
  //# Readjust invald configurations
  maxIdx = xAxisData.length - 1;
  if (selection.endIdx > maxIdx) {
    selection.endIdx = maxIdx;
  }
  if (selection.startIdx >= selection.endIdx) {
    selection.startIdx = selection.endIdx - 1;
  }
  if (selection.startIdx < 0) {
    selection.startIdx = 0;
  }
  if (selection.startIdx === selection.endIdx) {
    selection.endIdx++;
  }
  if (onRangeSelect != null) {
    //# communicate change and redraw chart
    onRangeSelect(selection);
  }
  redrawChart();
};

